{"command": "python3 - <<'PY'
import glob, json, os, re
from collections import Counter

error_counts = Counter()
failed_logins = Counter()
db_timeouts = []
slow_requests = 0

for path in glob.glob("logs/*"):
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            if path.endswith(".jsonl"):
                record = json.loads(line)
                timestamp = record["ts"]
                level = record["level"]
                service = record["service"]
                message = record["msg"]
            else:
                timestamp, level, service, message = re.match(
                    r"^(\S+)\s+(\S+)\s+\[([^\]]+)\]\s+(.*)$", line
                ).groups()

            if level == "ERROR":
                error_counts[service] += 1

            if service == "auth" and level == "WARN" and "login failed" in message:
                failed_logins[re.search(r"\buser=(\S+)", message).group(1)] += 1

            if "db timeout" in message.lower():
                db_timeouts.append(timestamp)

            if "request done" in message:
                latency = int(re.search(r"\blatency_ms=(\d+)", message).group(1))
                if latency > 2000:
                    slow_requests += 1

services = ["api", "auth", "billing", "cache", "search", "worker"]
incident = {
    "error_counts": {service: error_counts[service] for service in services},
    "top_user_by_failed_logins": failed_logins.most_common(1)[0][0],
    "first_db_timeout": min(db_timeouts),
    "requests_over_2000ms": slow_requests,
}

with open("incident.json", "w", encoding="utf-8") as fh:
    json.dump(incident, fh, indent=2)
    fh.write("\n")

print(json.dumps(incident, indent=2))
PY
cat incident.json"}

